export default function LogoLineIntro() {
  const pathRef = useRef<SVGPathElement>(null);
  const [visible, setVisible] = useState(false);
  const [fadeOut, setFadeOut] = useState(false);

  useEffect(() => {
    let alreadyShown = true;
    try {
      alreadyShown = sessionStorage.getItem(STORAGE_KEY) === "1";
    } catch {}
    if (alreadyShown) return;

    setVisible(true);
    try {
      sessionStorage.setItem(STORAGE_KEY, "1");
    } catch {}

    const fadeTimer = setTimeout(() => setFadeOut(true), 1500);
    const removeTimer = setTimeout(() => setVisible(false), 2000);
    return () => {
      clearTimeout(fadeTimer);
      clearTimeout(removeTimer);
    };
  }, []);

  useEffect(() => {
    if (!visible || !pathRef.current) return;
    const length = pathRef.current.getTotalLength();
    pathRef.current.style.strokeDasharray = `${length}`;
    pathRef.current.style.strokeDashoffset = `${length}`;
    pathRef.current.getBoundingClientRect();
    pathRef.current.style.transition = "stroke-dashoffset 1.1s ease-in-out, fill 0.4s ease-in 0.9s";
    pathRef.current.style.strokeDashoffset = "0";
    pathRef.current.style.fill = "#A6A916";
  }, [visible]);

  if (!visible) return null;

  return (
    <div
      className={`fixed inset-0 z-[100] flex items-center justify-center bg-brand-black transition-opacity duration-500 ${
        fadeOut ? "pointer-events-none opacity-0" : "opacity-100"
      }`}
    >
      <svg width="180" height="84" viewBox="0 0 474 221" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path ref={pathRef} d={LOGO_PATH} fill="none" stroke="#A6A916" strokeWidth={3} />
      </svg>
    </div>
  );
}
